create table RB_FUND_DIRECTION_DETAILS (SEQ_NO VARCHAR(50) not null  ,CLIENT_NO VARCHAR(22) not null  ,BASE_ACCT_NO VARCHAR(50) null  ,PROD_TYPE VARCHAR(20) null  ,CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,AGENT_NAME VARCHAR(100) null  ,REG_TYPE VARCHAR(1) null  ,FUND_SOURCE VARCHAR(1) null  ,FUND_FROM_ACCT_NO VARCHAR(50) null  ,FUND_FROM_NAME VARCHAR(100) null  ,FUND_FROM_BANK_NO VARCHAR(12) null  ,FUND_TO_ACCT_NO VARCHAR(50) null  ,FUND_TO_NAME VARCHAR(100) null  ,FUND_TO_BANK_NO VARCHAR(12) null  ,FUND_ACCT_PURPOSE VARCHAR(1) null  ,BAB_INTERNAL_BASE_ACCT_NO VARCHAR(50) null  ,DOCUMENT_TYPE VARCHAR(6) null  ,DOCUMENT_ID VARCHAR(40) null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  , primary key(SEQ_NO,CLIENT_NO));